function insertSlotsHTML(track,master=false,limit=null){
  const slots=master?masteringSettings(project.mastering).inserts:track.inserts,registry=master?MASTER_MODULES:EFFECTS,owner=master?'master':track.id,state=master?masteringSettings(project.mastering):track.effects;
  return `<div class="insert-slots ${limit?'compact-inserts':''}">${slots.slice(0,limit||slots.length).map((id,i)=>{const letter=String.fromCharCode(65+i),name=id?(master?registry[id]:effectDefinition(id)).name:'Aucun insert',on=id&&state[id].enabled,attrs=`data-insert-track="${owner}" data-insert-master="${master}"`;return `<div class="insert-slot ${id?'occupied':'empty'} ${id&&!on?'insert-bypassed':''}"><span>${letter}</span><button ${id?`data-insert-open="${id}"`:`data-insert-slot="${i}"`} ${attrs} aria-label="${id?'Ouvrir '+name:'Choisir le plugin de l’insert '+letter} sur ${master?'MASTER':esc(track.name)}" title="${name}${id&&!on?' · Bypass':''}">${id?name:'—'}</button>${id?`<button class="insert-options" data-insert-slot="${i}" ${attrs} aria-label="Options de l’insert ${letter} sur ${master?'MASTER':esc(track.name)}" title="Remplacer, bypasser, déplacer, retirer">⋯</button>`:''}</div>`;}).join('')}</div>`;
}
function openInsertMenu(trackId,index,master=false,preferred=null){
  const track=master?null:project.tracks.find(t=>t.id===trackId);if(!master&&!track)return;
  if(master)project.mastering=masteringSettings(project.mastering);else ensurePlugins(track);
  const slots=master?project.mastering.inserts:track.inserts,registry=master?MASTER_MODULES:EFFECTS,state=master?project.mastering:track.effects;
  if(index<0||index>=slots.length){toast('Tous les inserts sont occupés. Retire un module pour en choisir un autre.');return;}
  const id=slots[index],letter=String.fromCharCode(65+index),name=master?'MASTER':track.name;
  modal(`Insert ${letter} · ${name}`,`<div class="insert-menu"><label>PLUGIN<select id="insertChoice" aria-label="Plugin de l’insert ${letter}"><option value="">Aucun insert</option>${id&&!master&&id.includes('__')?`<option value="${id}" selected>${effectDefinition(id).name} · instance</option>`:''}${Object.entries(registry).map(([key,def])=>`<option value="${key}" ${key===id?'selected':''} ${master&&slots.includes(key)&&key!==id?'disabled':''}>${def.name} · ${def.subtitle}${master&&slots.includes(key)&&key!==id?' (déjà inséré)':''}</option>`).join('')}</select></label>${preferred&&!id?`<button class="primary-btn" id="insertPreferred">Insérer ${registry[preferred].name} ici</button>`:''}${id?`<div class="insert-menu-actions"><button class="outline-btn" id="editCurrentInsert">Ouvrir ${(master?registry[id]:effectDefinition(id)).name}</button><button class="outline-btn" id="bypassCurrentInsert">${state[id].enabled?'Bypasser':'Réactiver'}</button><button class="outline-btn" id="removeCurrentInsert">Retirer</button></div><label>DÉPLACER VERS<select id="insertDestination" aria-label="Destination de l’insert">${slots.map((key,i)=>`<option value="${i}" ${i===index?'selected':''}>${String.fromCharCode(65+i)} · ${key?(master?registry[key]:effectDefinition(key)).name:'Vide'}</option>`).join('')}</select></label><button class="outline-btn" id="moveCurrentInsert">Déplacer / échanger</button>${!master?'<button class="outline-btn" id="copyCurrentInsert">Copier vers cet emplacement vide</button>':''}`:''}<p>Traitement de haut en bas. Un module bypassé garde ses réglages et son emplacement.</p></div>`,'WARLIKE / INSERTS');
  const refresh=()=>{changed(true);$('modal').close();};
  const place=value=>{checkpoint();if(master){const previous=slots[index];slots[index]=value;if(previous&&previous!==value)state[previous].enabled=false;if(value)state[value].enabled=true;}else value=placeInsert(track,index,value);refresh();if(value&&!master)openPluginWindow(value,track.id);};
  $('insertChoice').onchange=e=>place(e.target.value||null);
  if($('insertPreferred'))$('insertPreferred').onclick=()=>place(preferred);
  if(!id)return;
  $('editCurrentInsert').onclick=()=>{$('modal').close();if(master)setView('mastering');else openPluginWindow(id,track.id);};
  $('removeCurrentInsert').onclick=()=>place(null);
  $('bypassCurrentInsert').onclick=()=>{checkpoint();state[id].enabled=!state[id].enabled;refresh();};
  if($('copyCurrentInsert'))$('copyCurrentInsert').onclick=()=>{try{const to=Number($('insertDestination').value);checkpoint();copyInsert(track,index,to);refresh();}catch(error){toast(error.message);}};
  $('moveCurrentInsert').onclick=()=>{const to=Number($('insertDestination').value);if(to===index)return;checkpoint();if(master)[slots[index],slots[to]]=[slots[to],slots[index]];else moveInsert(track,index,to);refresh();};
}
function panLabel(v){return Math.abs(v)<.01?'CENTRE':`${Math.round(Math.abs(v)*100)}${v<0?' L':' R'}`;}
let masterPeakHold=-Infinity;
const masterMeterSamples=[new Float32Array(2048),new Float32Array(2048)];
