function updateMasterMeters(){
  if(view!=='mastering')return;const chain=engine.graph?.mastering,levels=[];let sum=0,count=0;
  for(let c=0;c<2;c++){const data=masterMeterSamples[c];if(chain)chain.meters[c].getFloatTimeDomainData(data);else data.fill(0);let peak=0;for(const sample of data){peak=Math.max(peak,Math.abs(sample));sum+=sample*sample;count++;}levels.push(peak);const db=peak>0?20*Math.log10(peak):-Infinity;const bar=document.querySelector(`[data-master-meter="${c}"]`),label=document.querySelector(`[data-master-level="${c}"]`);if(bar)bar.style.width=Math.max(0,Math.min(100,(db+60)/60*100))+'%';if(label)label.textContent=Number.isFinite(db)?db.toFixed(1):'−∞';}
  const peak=Math.max(...levels),peakDb=peak>0?20*Math.log10(peak):-Infinity,rmsDb=sum>0?20*Math.log10(Math.sqrt(sum/count)):-Infinity;masterPeakHold=Math.max(masterPeakHold,peakDb);
  for(const [key,value] of [['peak',peakDb],['rms',rmsDb],['hold',masterPeakHold]]){const node=document.querySelector(`[data-master-${key}]`);if(node){node.textContent=Number.isFinite(value)?value.toFixed(1):'−∞';node.classList.toggle('hot',value>=-.1);}}
  for(const id of ['press','peak']){const node=document.querySelector(`[data-master-gr="${id}"]`);if(node)node.textContent=(!project.mastering.bypass&&project.mastering[id].enabled?(chain?.[id==='press'?'press':'limiter'].reduction||0):0).toFixed(1)+' dB';}
}
