function validateProject(p){
  if(!p||p.version!==1||!Array.isArray(p.tracks)||!p.tracks.length||p.tracks.length>64)throw new Error('Projet Warlike Studio non reconnu.');
  if(!Number.isFinite(p.bpm)||p.bpm<40||p.bpm>240||!Number.isInteger(p.bars)||p.bars<1||p.bars>MAX_BARS||typeof p.name!=='string')throw new Error('Paramètres du projet invalides.');
  const audio=p.audioSetup||{};p.audioSetup={deviceId:typeof audio.deviceId==='string'?audio.deviceId.slice(0,500):'',channel:['1','2','stereo'].includes(audio.channel)?audio.channel:'1',monitor:audio.monitor===true,latencyMs:Math.max(-500,Math.min(1000,Number.isFinite(audio.latencyMs)?audio.latencyMs:0)),keepTakes:audio.keepTakes!==false};p.delayCompensation=p.delayCompensation!==false;
  p.patterns=(Array.isArray(p.patterns)?p.patterns:[]).slice(0,128).filter(a=>a&&typeof a.id==='string').map(a=>({...a,name:String(a.name||'Pattern').slice(0,60),bars:Math.max(1,Math.min(32,Math.round(Number(a.bars)||2))),channels:a.channels&&typeof a.channels==='object'?a.channels:{}}));for(const pat of p.patterns)for(const data of Object.values(pat.channels)){if(data.notes)data.notes=normalizeNotes(data.notes,pat.bars*16);if(data.pattern)for(const voice of Object.keys(data.pattern))data.pattern[voice]=Array.from({length:pat.bars*16},(_,i)=>Math.max(0,Math.min(1,Number(data.pattern[voice]?.[i])||0)));}
  p.swing=Math.max(0,Math.min(75,Number(p.swing)||0));p.recording=recordingSettings(p.recording);p.mastering=masteringSettings(p.mastering);
  const trackIds=new Set(),clipIds=new Set();
  for(const tr of p.tracks){if(!['audio','bus',...Object.keys(INSTRUMENTS)].includes(tr.type)||typeof tr.id!=='string'||trackIds.has(tr.id)||!Array.isArray(tr.clips)||tr.clips.length>512)throw new Error('Piste invalide.');trackIds.add(tr.id);if(!/^[a-z0-9]+$/i.test(tr.id))throw new Error('Identifiant de piste invalide.');if(!/^#[0-9a-f]{6}$/i.test(tr.color))tr.color='#94b7aa';tr.name=String(tr.name).slice(0,60);tr.volume=Math.max(-48,Math.min(12,Number(tr.volume)||0));tr.pan=Math.max(-1,Math.min(1,Number(tr.pan)||0));tr.mute=!!tr.mute;tr.solo=!!tr.solo;ensurePlugins(tr);
    for(const [key,def] of Object.entries(tr.effects).map(([id])=>[id,effectDefinition(id)])){const state=tr.effects[key]||{};for(const c of def.controls)state[c.key]=Math.max(c.min,Math.min(c.max,(Number.isFinite(state[c.key])?state[c.key]:c.default)));state.enabled=state.enabled===true&&tr.inserts.includes(key);tr.effects[key]=state;}
    tr.playlists=(Array.isArray(tr.playlists)?tr.playlists:[]).slice(0,64).filter(l=>l&&typeof l.id==='string'&&Array.isArray(l.clips)&&l.clips.length<=512).map(l=>({...l,name:String(l.name||'Prise').slice(0,60),clips:l.clips.filter(c=>c&&typeof c.id==='string'&&Number.isFinite(c.start)&&c.start>=0&&Number.isFinite(c.length)&&c.length>0&&c.start+c.length<=MAX_BARS+.01&&typeof c.audioId==='string')}));
    const params=automationParameters(tr),curves={};for(const def of params)if(tr.automation?.curves?.[def.key])curves[def.key]=normaliseCurve(tr.automation.curves[def.key],def.min,def.max,p.bars);tr.automation={mode:['read','write'].includes(tr.automation?.mode)?tr.automation.mode:'off',curves};
    for(const c of INSTRUMENTS[tr.type]?.controls||[])tr.instrument[c.key]=Math.max(c.min,Math.min(c.max,(Number.isFinite(tr.instrument[c.key])?tr.instrument[c.key]:c.default)));
    tr.tune={key:Math.round(Math.max(0,Math.min(11,Number(tr.tune.key)||0))),scale:['minor','major','chromatic'].includes(tr.tune.scale)?tr.tune.scale:'minor',speed:Math.max(0,Math.min(250,Number(tr.tune.speed)||0)),amount:Math.max(0,Math.min(1,Number(tr.tune.amount)||0)),mix:Math.max(0,Math.min(1,Number(tr.tune.mix)||0))};
    for(const c of tr.clips){if(typeof c.id!=='string'||!/^[a-z0-9]+$/i.test(c.id)||clipIds.has(c.id)||!Number.isFinite(c.start)||c.start<0||!Number.isFinite(c.length)||c.length<=0||c.start+c.length>MAX_BARS+.01)throw new Error('Clip invalide.');clipIds.add(c.id);c.name=String(c.name).slice(0,100);
      if(c.audioId&&typeof c.audioId!=='string')throw new Error('Référence audio invalide.');c.gainDb=clampClipGain(c.gainDb);c.fadeIn=Math.max(0,Math.min(60,Number.isFinite(c.fadeIn)?c.fadeIn:.005));c.fadeOut=Math.max(0,Math.min(60,Number.isFinite(c.fadeOut)?c.fadeOut:.005));c.fadeCurve=c.fadeCurve==='equalPower'?'equalPower':'linear';c.sourceOffset=Math.max(0,Number.isFinite(c.sourceOffset)?c.sourceOffset:0);c.patternOffset=Math.max(0,Number.isFinite(c.patternOffset)?c.patternOffset:0);
      if(tr.type==='drums'&&!c.audioId){c.patternSteps=Math.max(16,Math.min(512,Number(c.patternSteps)||16));c.pattern=Object.fromEntries(Object.keys(DRUM_VOICES).map(v=>[v,Array.from({length:c.patternSteps},(_,i)=>Math.max(0,Math.min(1,Number(c.pattern?.[v]?.[i])||0)))]));}
      if(tr.type!=='drums'&&tr.type!=='bus'&&!c.audioId){c.patternSteps=Math.max(16,Math.min(512,Number(c.patternSteps)||32));c.notes=normalizeNotes(c.notes,c.patternSteps);}
    }
  }normaliseRouting(p);
}
async function openProject(file){if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=='chayah-studio')throw new Error('Ce fichier n’est pas un projet Warlike Studio.');validateProject(data.project);await engine.init();const decoded=new Map();for(const a of data.assets||[]){if(typeof a.id!=='string'||typeof a.name!=='string'||typeof a.data!=='string')throw new Error('Audio invalide.');const raw=fromBase64(a.data),buffer=await engine.ctx.decodeAudioData(raw.slice(0));decoded.set(a.id,{name:a.name,data:raw,buffer});}engine.stop();checkpoint();project=data.project;assets=new Map([...assets,...decoded]);engine.masterVolume=Math.max(-48,Math.min(3,(Number.isFinite(data.masterVolume)?data.masterVolume:-2)));selectedTrack=project.tracks[0].id;selectedClip=project.tracks[0].clips[0]?.id;changed(true);toast('Projet ouvert.');}catch(e){toast('Ouverture impossible : '+e.message);}}
async function exportWav(){if(recording){toast('Termine la prise avant d’exporter.');return;}if(project.tracks.some(t=>t.clips.some(c=>c.audioId&&!assets.has(c.audioId)))){toast('Un fichier audio est manquant. Réimporte-le avant l’export.');return;}const btn=$('exportWav');btn.disabled=true;btn.innerHTML=icon('wave')+' Rendu du mix…';try{const wav=await engine.exportWav();download(wav,safeName()+'.wav','audio/wav');toast('Mix exporté · WAV stéréo 44,1 kHz / 16 bits.');}catch(e){toast('Export impossible : '+e.message);}finally{btn.disabled=false;btn.innerHTML=icon('download')+' Exporter <span>WAV</span>';}}

