$('loop').onclick=()=>{if(recording){toast('La boucle est suspendue pendant une prise.');return;}engine.loop=!engine.loop;$('loop').classList.toggle('active',engine.loop);$('loop').setAttribute('aria-pressed',engine.loop);};
$('metronome').onclick=()=>{engine.metronome=!engine.metronome;$('metronome').classList.toggle('active',engine.metronome);$('metronome').setAttribute('aria-pressed',engine.metronome);};
$('bpm').onchange=()=>{const n=Math.round(Math.max(40,Math.min(240,Number($('bpm').value)||138)));if(recording){$('bpm').value=project.bpm;toast('Change le tempo après la prise.');return;}if(project.tracks.some(t=>t.frozenTrack)){toast('Dégèle les pistes avant de changer le tempo.');$('bpm').value=project.bpm;return;}if(project.tracks.some(t=>t.type==='audio'&&t.clips.some(c=>(c.start+c.length)*n/project.bpm>MAX_BARS))){toast('Ce tempo dépasserait la longueur maximale de la session audio.');$('bpm').value=project.bpm;return;}const playing=engine.playing,ratio=n/project.bpm;engine.pause();checkpoint();changeAudioTempo(project,n);engine.position*=ratio;changed(true);$('bpm').value=n;drawClips();if(playing)engine.play();updateTransport();};
$('bars').onchange=()=>{const n=sessionBars($('bars').value),last=Math.max(0,...project.tracks.flatMap(t=>t.clips.map(c=>c.start+c.length)));if(last>n+.001){$('bars').value=project.bars;toast('Déplace ou raccourcis les clips qui dépassent avant de réduire le projet.');return;}checkpoint();project.bars=n;if(engine.position>=n*16)engine.seek(0);changed(true);};
$('projectName').onchange=()=>{checkpoint();project.name=$('projectName').value.trim()||'Nouvelle session';$('projectName').value=project.name;save();};
